window.ScripturaLexicons.BDAG_PART_0145 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heptakiskhilioi-bdag\" data-source=\"BDAG\" data-search=\"ἑπτακισχίλιοι, αι, α heptakiskhílioi numeral cardinal sete mil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑπτακισχίλιοι, αι, α</td><td>numeral cardinal</td><td>sete mil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heptaplasion-bdag\" data-source=\"BDAG\" data-search=\"ἑπταπλασίων, ον, heptaplasíōn adjetivo; genitivo -ονος sete vezes maior; sétuplo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑπταπλασίων, ον,</td><td>adjetivo; genitivo -ονος</td><td>sete vezes maior; sétuplo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heptaplasios-bdag\" data-source=\"BDAG\" data-search=\"ἑπταπλασίως heptaplasíōs advérbio sete vezes; de modo sétuplo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑπταπλασίως</td><td>advérbio</td><td>sete vezes; de modo sétuplo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-erastos-bdag\" data-source=\"BDAG\" data-search=\"Ἔραστος, ου, ὁ Érastos nome próprio masculino Erasto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἔραστος, ου, ὁ</td><td>nome próprio masculino</td><td>Erasto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eraunao-bdag\" data-source=\"BDAG\" data-search=\"ἐραυνάω eraunáō verbo; variante ortográfica posterior investigar; examinar; esquadrinhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐραυνάω</td><td>verbo; variante ortográfica posterior</td><td>investigar; examinar; esquadrinhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eraunetes-bdag\" data-source=\"BDAG\" data-search=\"ἐραυνητής, οῦ, ὁ eraunētḗs substantivo masculino investigador; examinador; aquele que esquadrinha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐραυνητής, οῦ, ὁ</td><td>substantivo masculino</td><td>investigador; examinador; aquele que esquadrinha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-erao-bdag\" data-source=\"BDAG\" data-search=\"ἐράω eráō verbo; ativo e passivo desejar ardentemente; anelar; amar apaixonadamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐράω</td><td>verbo; ativo e passivo</td><td>desejar ardentemente; anelar; amar apaixonadamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergazomai-bdag\" data-source=\"BDAG\" data-search=\"ἐργάζομαι ergázomai verbo; depoente médio; passivo trabalhar; exercer atividade; realizar; praticar; produzir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐργάζομαι</td><td>verbo; depoente médio; passivo</td><td>trabalhar; exercer atividade; realizar; praticar; produzir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergasia-bdag\" data-source=\"BDAG\" data-search=\"ἐργασία, ας, ἡ ergasía substantivo feminino atividade; prática; trabalho; negócio; lucro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐργασία, ας, ἡ</td><td>substantivo feminino</td><td>atividade; prática; trabalho; negócio; lucro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergasterion-bdag\" data-source=\"BDAG\" data-search=\"ἐργαστήριον, ίου, τό ergastḗrion substantivo neutro oficina; lugar de trabalho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐργαστήριον, ίου, τό</td><td>substantivo neutro</td><td>oficina; lugar de trabalho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergastra-bdag\" data-source=\"BDAG\" data-search=\"ἔργαστρα, ων, τά érgastra substantivo neutro plural oficinas; locais de trabalho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔργαστρα, ων, τά</td><td>substantivo neutro plural</td><td>oficinas; locais de trabalho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergates-bdag\" data-source=\"BDAG\" data-search=\"ἐργάτης, ου, ὁ ergátēs substantivo masculino trabalhador; operário; obreiro; praticante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐργάτης, ου, ὁ</td><td>substantivo masculino</td><td>trabalhador; operário; obreiro; praticante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergon-bdag\" data-source=\"BDAG\" data-search=\"ἔργον, ου, τό érgon substantivo neutro obra; ação; feito; trabalho; tarefa; produto; assunto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔργον, ου, τό</td><td>substantivo neutro</td><td>obra; ação; feito; trabalho; tarefa; produto; assunto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ergoparektes-bdag\" data-source=\"BDAG\" data-search=\"ἐργοπαρέκτης, ου, ὁ ergoparéktēs substantivo masculino; hápax empregador; aquele que oferece trabalho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐργοπαρέκτης, ου, ὁ</td><td>substantivo masculino; hápax</td><td>empregador; aquele que oferece trabalho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-erethizo-bdag\" data-source=\"BDAG\" data-search=\"ἐρεθίζω erethízō verbo provocar; instigar; irritar; estimular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐρεθίζω</td><td>verbo</td><td>provocar; instigar; irritar; estimular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ereido-bdag\" data-source=\"BDAG\" data-search=\"ἐρείδω ereídō verbo fincar; cravar; prender firmemente; ficar preso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐρείδω</td><td>verbo</td><td>fincar; cravar; prender firmemente; ficar preso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ereugomai-bdag\" data-source=\"BDAG\" data-search=\"ἐρεύγομαι ereúgomai verbo; depoente médio proferir; anunciar; declarar vigorosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐρεύγομαι</td><td>verbo; depoente médio</td><td>proferir; anunciar; declarar vigorosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ereunao-bdag\" data-source=\"BDAG\" data-search=\"ἐρευνάω ereunáō verbo; remissão ver ἐραυνάω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐρευνάω</td><td>verbo; remissão</td><td>ver ἐραυνάω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ereunetes-bdag\" data-source=\"BDAG\" data-search=\"ἐρευνητής ereunētḗs substantivo; remissão ver ἐραυνητής BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐρευνητής</td><td>substantivo; remissão</td><td>ver ἐραυνητής</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eremia-bdag\" data-source=\"BDAG\" data-search=\"ἐρημία, ας, ἡ erēmía substantivo feminino região deserta; deserto; lugar ermo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐρημία, ας, ἡ</td><td>substantivo feminino</td><td>região deserta; deserto; lugar ermo</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-heptakiskhilioi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑπτακισχίλιοι, αι, α</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heptakiskhílioi⟧</span><span class=\"separator\">·</span><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior e <span class=\"greek\">χίλιοι</span>; Heródoto e outros; GDI IV, 1210, n.º 3 II, 25 [séc. I a.C., Sicília]; LXX.) <b>Sete mil</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:4</a> (Just., D. 39, 1 e outras passagens; conforme 3 Km 19:18: <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">χιλιάδας</span>). — TW.</p></section></article>\n<article id=\"entry-heptaplasion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑπταπλασίων, ον,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heptaplasíōn⟧</span><span class=\"separator\">·</span><span>adjetivo; genitivo -ονος</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo -<span class=\"greek\">ονος</span> (ver o verbete seguinte; Oribásio, Ecl. 89, 22: CMG VI 2, 2, p. 269, 9; 2 Km 12:6; Sl 78:12; TestAbr B 8, p. 112, 24 [Stone, p. 72]; ApcZeph; Jos., Ant. 1, 77; AcPh 20 [Aa II/2, 11, 1s.]). <b>Sétuplo, sete vezes mais.</b> <span class=\"greek\">ἑπταπλασίονα</span> (<span class=\"greek\">ἀπο</span>)<span class=\"greek\">λαμβάνειν</span>, <i>receber sete vezes mais em retribuição</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:30</a>, códice D (cf. Sir 35:10; G. Kilpatrick, em <i>Neotestamentica et Semitica</i> [1969], p. 203). — Comparar <span class=\"greek\">διπλάσιος</span>; DELG.</p></section></article>\n<article id=\"entry-heptaplasios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑπταπλασίως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heptaplasíōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; LXX; adjetivo em Platão, Ep. 7, 332a; Eutócio [Arquimedes, <i>Op. Omn.</i>, ed. J. Heiberg, III, 1915], p. 244, 24.) <b>Sete vezes, de maneira sétupla</b>, Hs 6, 4, 2.</p></section></article>\n<article id=\"entry-erastos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἔραστος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Érastos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Erasto</b>, nome pessoal encontrado na literatura e em inscrições (ver SIG 838, 6).</p>\n<p class=\"entry-text\"><b>① Um cristão em Corinto</b>, designado <span class=\"greek\">οἰκονόμος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, <i>tesoureiro da cidade</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:23</a>. Uma inscrição latina de Corinto, publicada nos estudos citados abaixo, menciona um funcionário chamado Erasto.</p>\n<p class=\"entry-text\"><b>② Um companheiro de Paulo</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:22</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:20</a>.</p>\n<p class=\"entry-text\">— F. de Waele, «Erastus», <i>Mededeelingen van het Nederlandsch Historisch Instituut te Rome</i> 9 (1929), pp. 40–48; H. Cadbury, «Erastus of Corinth», JBL 50 (1931), pp. 42–58; W. Miller, «Who was Erastus?», <i>Bibliotheca Sacra</i> 88 (1931), pp. 342–346; C. Hemer, <i>Acts</i>, pp. 235, 260, nota 32; Boffo, <i>Iscrizioni</i>, n.º 43; BHHW I, p. 422; LGPN I; M-M.</p></section></article>\n<article id=\"entry-eraunao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐραυνάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eraunáō⟧</span><span class=\"separator\">·</span><span>verbo; variante ortográfica posterior</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte.) Forma posterior de <span class=\"greek\">ἐρευνάω</span>, atestada em inscrições desde a época de Pompeu (IG XII/5, 653, 21) e nos papiros desde 22 d.C. (POxy 294, 9s.); o verbo em geral ocorre desde Homero. Ver B-D-F §30, 4; W-S. §5, 21a; Mlt-H., p. 86; Thumb, p. 176s.; E. Nachmanson, <i>Eranos</i> 11 (1911), p. 239; J. Wackernagel, TLZ 33 (1908), p. 37; quanto à LXX, Thackeray, p. 79, e Helbing, p. 7.</p>\n<p class=\"entry-text\"><b>Empenhar-se cuidadosa ou exaustivamente em conhecer alguma coisa: pesquisar, examinar, investigar, esquadrinhar.</b> Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i>: <span class=\"greek\">τὰς</span> <span class=\"greek\">γραφάς</span>, <i>as Escrituras</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:39</a> (H. Bell, ZNW 37 [1939], pp. 10–13); <span class=\"greek\">καρδίας</span>, <i>corações</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:27</a>; <span class=\"greek\">νεφροὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καρδίας</span>, <i>rins (figuradamente, a mente) e corações</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:23</a>; <span class=\"greek\">τὴν</span> <span class=\"greek\">φύσιν</span> <span class=\"greek\">αὐτῆς</span>, <i>sua natureza</i>, GJs 19:3; 20:1.</p>\n<p class=\"entry-text\">Acerca do Espírito: <span class=\"greek\">πάντα</span>, <i>sonda todas as coisas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 2:10</a> (Horápolo 1, 34: <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐξερευνᾷ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span>, «o sol esquadrinha tudo»). <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">λύχνος</span> <span class=\"greek\">ἐραυνῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ταμιεῖα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γαστρός</span>, <i>o espírito do Senhor é uma lâmpada que ilumina os depósitos das partes interiores</i>, isto é, a vida interior, 1 Cl 21:2 (Pv 20:27).</p>\n<p class=\"entry-text\">Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, <i>investigar algo</i>, B 4:1; Hm 10, 1, 4, 6. Seguido de pergunta indireta, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:11</a>. Em uso absoluto: <span class=\"greek\">ἐραύνησον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἴδε</span>, <i>examina e vê</i> (4 Km 10:23), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.52\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:52</a>; <span class=\"greek\">ἠραύνησεν</span>, GJs 1:3. — DELG, s.v. <span class=\"greek\">ἐρέω</span>; M-M; TW.</p></section></article>\n<article id=\"entry-eraunetes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐραυνητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eraunētḗs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; esta grafia em PFay 104 [séc. III d.C.]; como <span class=\"greek\">ἐρευνητής</span>, em Clearco, fragmento 19s. [Ateneu 6, 256a], Jos., Ant. 17, 110 e outros; UPZ 149, 15 [cerca de 200 a.C.].) <b>Quem realiza uma investigação cuidadosa ou exaustiva: investigador, examinador.</b> Sobre Deus: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐννοιῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐνθυμήσεων</span>, <i>aquele que esquadrinha pensamentos e reflexões</i>, 1 Cl 21:9.</p></section></article>\n<article id=\"entry-erao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐράω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eráō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperativo <span class=\"greek\">ἐράτω</span> (Píndaro, Heródoto e outros; PSI 406, 36 [séc. III a.C.]; Fílon, Justino, Taciano, Atenágoras; o substantivo <span class=\"greek\">ἔρως</span> em Just., D. 8, 1, refere-se ao afeto pelos profetas e pelos «amigos de Cristo»). De <span class=\"greek\">ἔραμαι</span> (Homero e outros; por exemplo primeiro aoristo médio <span class=\"greek\">ἠρασάμην</span>, Il. 14, 316b; Atenágoras 21, 4), primeiro aoristo passivo <span class=\"greek\">ἠράσθην</span>.</p>\n<p class=\"entry-text\">Frequentemente empregado para <i>atração sexual</i>, como Heródoto 9, 108; Xen., Cyr. 5, 1, 10; daí, como em nossa literatura, <b>sentir paixão por algo, desejar ardentemente, anelar, ter fervor por</b>. Com genitivo <span class=\"greek\">τινός</span>, <i>de alguma coisa</i> (Ésquilo, Eum. 852: <span class=\"greek\">γῆς</span>; Herm. Wr. 6, 4b; Pv 4:6; Fílon, Spec. Leg. 2, 258: <span class=\"greek\">ἀληθείας</span>): <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, <i>da carne</i>, IRo 2:1. <b>Desejar, anelar por</b> (Il. 9, 64): <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀποθανεῖν</span>, <i>desejar morrer</i>, IRo 7:2.</p>\n<p class=\"entry-text\">Seguido de infinitivo (Píndaro e outros): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοινοῦ</span> <span class=\"greek\">ἐλευθεροῦσθαι</span>, <i>desejar libertar-se (da escravidão) à custa da comunidade</i>, IPol 4:3 (a expressão, em vista do sutil jogo de palavras sugerido pela oração final, aparentemente evoca o sentido sensual que a palavra tem em certos contextos externos à nossa literatura; ver acima). — B. Warfield, «The Terminology of Love in the NT», PTR 16 (1918), pp. 1–45, 153–203. — DELG, s.v. <span class=\"greek\">ἔραμαι</span>; TW; Sv.</p></section></article>\n<article id=\"entry-ergazomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐργάζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ergázomai⟧</span><span class=\"separator\">·</span><span>verbo; depoente médio; passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἠργαζόμην</span> (nas edições também <span class=\"greek\">εἰργ</span>-, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:3</a>); futuro, segunda pessoa do singular <span class=\"greek\">ἐργᾷ</span>, terceira pessoa do singular <span class=\"greek\">ἐργᾶται</span> e terceira pessoa do plural <span class=\"greek\">ἐργῶνται</span> (todas na LXX); primeiro aoristo <span class=\"greek\">εἰργασάμην</span> (2 Jo 8; outras edições: <span class=\"greek\">ἠρ</span>-); perfeito, terceira pessoa do singular <span class=\"greek\">εἴργασται</span>, LXX; particípio <span class=\"greek\">εἰργασμένος</span> (sobre o aumento, ver Mayser, p. 332; Meisterhans³–Schwyzer, p. 171; B-D-F §67, 3; Moulton, ClR 15 [1901], pp. 35s.; Mlt-H., pp. 189s.); passivo: futuro, terceira pessoa do singular <span class=\"greek\">ἐργασθήσεται</span>, Ez 36:34; En 10:18 (ver <span class=\"greek\">ἔργον</span> e o verbete seguinte; desde Homero).</p>\n<p class=\"entry-text\"><b>① Exercer atividade que exige esforço: trabalhar, estar ativo.</b> Intransitivo (Hesíodo, Heródoto e outros), D 12:3. <span class=\"greek\">ταῖς</span> <span class=\"greek\">χερσίν</span>, <i>trabalhar com as próprias mãos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 4:12</a> (<span class=\"greek\">ἐ</span>. <span class=\"greek\">ἰδίαις</span> <span class=\"greek\">χερσίν</span>, conforme Biogr., p. 253; sobre o desprezo pelo trabalho manual, cf. Jos., Ant. 17, 333); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 4:11</a> (ver <span class=\"greek\">ἴδιος</span> ③ⓐ); também <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span>, B 19:10. <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρας</span>, <i>trabalhar noite e dia</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 2:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 3:8</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀμπελῶνι</span>, <i>na vinha</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:28</a>.</p>\n<p class=\"entry-text\">Em uso absoluto: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:4</a>b; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:3</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 3:10</a>, 12; <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐργαζομένῳ</span>, <i>àquele que trabalha</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:4</a>; cf. versículo 5 (<span class=\"greek\">ἐργαζόμενοι</span> <span class=\"greek\">καλοί</span>, OdesSol 11:20) e <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:5</a>, códice D (<i>Unknown Sayings</i>, pp. 49–54). Acerca de Deus e Cristo: <b>trabalhar, estar em atividade</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:17</a> (cf. Máximo de Tiro 15, 6ef: Héracles deve trabalhar sem cessar, como Zeus, seu pai).</p>\n<p class=\"entry-text\">Acerca de atividade financeira: com uma soma de dinheiro (cinco talentos), <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span>, <i>negociar ou comerciar com eles</i> (Demóstenes 36, 44: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμπορίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χρήμασιν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:16</a>. — M. Balme, «Attitudes to Work and Leisure in Ancient Greece», <i>Greece and Rome</i>, segunda série, 31 (1984), pp. 140–152.</p>\n<p class=\"entry-text\"><b>② Fazer ou realizar alguma coisa mediante trabalho.</b> Uso transitivo.</p>\n<p class=\"entry-text\"><b>ⓐ Fazer, realizar, executar</b>, com acusativo (Élio Aristides 42, 13 K. = 6, p. 69 D.: <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἐργαζομένου</span> <span class=\"greek\">σου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, acerca de Asclépio). Com <span class=\"greek\">ἔργον</span>, <i>uma obra</i> (Xen., An. 6, 3, 17: <span class=\"greek\">κάλλιστον</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἐ</span>.; Platão, Polit. 1, 346d; Apiano, Celt. 18 §2; Bell. Civ. 2, 58 §238 e outros; Arriano, Anab. 7, 17, 3; PPetr II, 9 [2], 4 [séc. III a.C.]; Sir 51:30; TestSol D 4:8: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ὑμῶν</span>; Just., D. 88, 8: <span class=\"greek\">τεκτονικὰ</span> <span class=\"greek\">ἔργα</span>): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:41</a> (Hc 1:5); 1 Cl 33:8; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <i>realizar as obras de Deus</i> (cf. Nm 8:11), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:28</a>; 9:4; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">κυρίου</span>, <i>a obra do Senhor</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 16:10</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, <i>fazer algo a alguém</i> (Ps.-Demóstenes 53, 18): <span class=\"greek\">ἔργον</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, <i>praticar uma boa ação para com alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:10</a>; cf. B 21:2; 3 Jo 5. Também com <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:6</a>. Em sentido diferente: <span class=\"greek\">ἔργα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">εἰργασμένα</span>, <i>obras realizadas em Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:21</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span>, <i>fazer o bem</i> (cf. Dio Chrys. 16 [33], 15; GrBar 11:9; Jos., Ant. 6, 208: <span class=\"greek\">ἀγαθά</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:28</a>; Hm 2:4. Em oposição a <span class=\"greek\">ἐ</span>. <span class=\"greek\">πονηρόν</span> (Luciano, Catapl. 24), Hm 10, 2, 3. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πάντας</span>, <i>fazer o bem a todos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:10</a>. <span class=\"greek\">κακὸν</span> <span class=\"greek\">ἐ</span>., <i>fazer o mal</i> (Dio Chrys. 13 [7], 33; Paléfato 1 e 3; Just., D. 95, 1: <span class=\"greek\">κακά</span>; Atenágoras 11, 2: <span class=\"greek\">ἀεί</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐ</span>. … <span class=\"greek\">κακόν</span>): <span class=\"greek\">κακὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">ἐ</span>., <i>fazer mal ao próximo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:10</a> (cf. Pv 3:30; EpArist 273).</p>\n<p class=\"entry-text\">De modo geral, com objeto «alguma coisa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:23</a>; 2 Jo 8; <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἐ</span>., <i>não fazer trabalho algum</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 3:11</a>; <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δικαιοσύνῃ</span>, <i>nada fazer pela justiça</i>, Hs 5, 1, 4 (Ps.-Aristóteles, Mirabilia 142: <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἐργ</span>. = «nada realizar»).</p>\n<p class=\"entry-text\">Também com qualidades e conceitos (em Isócrates, com <span class=\"greek\">ἀρετήν</span>, <span class=\"greek\">σωφροσύνην</span>; em Fílon, Gig. 26, com <span class=\"greek\">τελειότητα</span>): <span class=\"greek\">δικαιοσύνην</span>, <i>praticar o que é justo</i> (Sl 14:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:35</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:33</a>; Hv 2, 2, 7; Hm 5, 1, 1; Hs 9, 13, 7. <span class=\"greek\">ἐ</span>. <span class=\"greek\">δικαιοσύνην</span> <span class=\"greek\">θεοῦ</span>, <i>fazer o que é justo diante de Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:20</a> (mas ver ②ⓒ abaixo; variante <span class=\"greek\">κατεργάζεσθαι</span>, ver esse lema). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνομίαν</span>, <i>praticar a iniquidade</i> (Sl 5:6; 6:9 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:23</a>; <span class=\"greek\">ἁμαρτίαν</span>, <i>cometer pecado</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:9</a> (Jos., Ant. 6, 124: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἁμάρτημα</span>). Sobre o efeito: <span class=\"greek\">τί</span> <span class=\"greek\">ἐργάζῃ</span>;, <i>que obra fazes?</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:30</a> (cf. Fílon, Leg. All. 3, 83; Taciano 25, 1: <span class=\"greek\">τί</span> <span class=\"greek\">μέγα</span> … <span class=\"greek\">ἐ</span>. <span class=\"greek\">φιλόσοφοι</span>;).</p>\n<p class=\"entry-text\"><b>ⓑ Praticar ou executar atividade especializada, oficiar.</b> (Com <span class=\"greek\">τέχνην</span> e outros termos em Xenofonte, Platão etc.): <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱερά</span>, <i>os ritos do templo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9:13</a> (cf. Nm 8:11).</p>\n<p class=\"entry-text\"><b>ⓒ Produzir um resultado, ocasionar, dar origem a.</b> (Ver o verbete seguinte, acepção ④; Sófocles, Ant. 326; Epicteto, fragmento em Estobeu 14: <span class=\"greek\">πενία</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">ἐργάζεται</span>; Just., A I, 45, 6: <span class=\"greek\">ὅπερ</span> … <span class=\"greek\">κόλασιν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">αἰωνίαν</span> <span class=\"greek\">ἐργάζεται</span>.) <span class=\"greek\">μετάνοιαν</span>, <i>produzir arrependimento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7:10</a>; <span class=\"greek\">ἐ</span>. <span class=\"greek\">δικαιοσύνην</span> <span class=\"greek\">θεοῦ</span>, <i>produzir uma justiça que subsista diante de Deus</i> (mas ver ②ⓐ), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:20</a>; <span class=\"greek\">θάνατον</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἐ</span>., <i>atrair a morte sobre si mesmos</i>, Hs 8, 8, 5 (Just., D. 124, 4).</p>\n<p class=\"entry-text\"><b>ⓓ Trabalhar em ou sobre algo.</b> (Com <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, «a terra», Gn 2:5; En 10:18; ApcMos 24.) <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, <i>trabalhar no mar para obter o sustento</i> (Aristóteles, Probl. 38, 2, 966b, 26; Dionísio de Halicarnasso 3, 46; Apiano, Liby. 2 §5; 84 §397; Luciano, Electr. 5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:17</a>; ver C. Lindhagen, <i><span class=\"greek\">ΕΡΓΑΖΕΣΘΑΙ</span></i> (1950), <i>Uppsala Univ. Årsskrift</i> 1950/5, pp. 5–26.</p>\n<p class=\"entry-text\"><b>ⓔ Trabalhar por alimento ou ganhá-lo.</b> (Hesíodo, Op. 43: <span class=\"greek\">βίον</span> <span class=\"greek\">ἐ</span>.; Heródoto 1, 24: <span class=\"greek\">χρήματα</span>; cf. Platão, Hipp. Mai. 282d; Laches 183a; Xen., Mem. 2, 8, 2; Teodocião, Pv 21:6; também <span class=\"greek\">βρῶμα</span> em Paléfato, p. 28, 10.) <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">βρῶσιν</span>, <i>trabalhar pelo alimento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:27</a>. Neste contexto, <span class=\"greek\">βρῶσις</span> parece ser a dádiva gratuita do Filho do Homem. Como no caso semelhante da samaritana (cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:35</a> com 4:14), os ouvintes são preparados para a declaração de que devem aceitar aquilo que é dado gratuitamente.</p>\n<p class=\"entry-text\">Entretanto, <span class=\"greek\">ἐργάζεσθαι</span>, quando empregado com alimento, também pode significar <b>preparar para uso, digerir, assimilar</b>, tendo como objeto subentendido <span class=\"greek\">τὴν</span> <span class=\"greek\">τροφήν</span> (Aristóteles, De Vita et Morte 4; Máximo de Tiro 15, 5a [<span class=\"greek\">ἐργ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">τροφήν</span>, acerca da atividade das mandíbulas]; mais frequentemente <span class=\"greek\">ἐργασία</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τροφῆς</span>). O composto <span class=\"greek\">κατεργάζεσθαι</span> é mais comum nesse sentido, mas é evitado nesta passagem por causa do jogo de palavras com <span class=\"greek\">ἐργάζεσθαι</span> no versículo 28. — DELG, s.v. <span class=\"greek\">ἔργον</span>; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-ergasia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐργασία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ergasía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; desde Píndaro; inscrições, papiros, LXX; En 8:1; TestSol, Josefo, Justino).</p>\n<p class=\"entry-text\"><b>① Envolvimento em atividade ou comportamento com interesse continuado: prática, ocupação, exercício.</b> Com genitivo <span class=\"greek\">τινός</span>, <i>de alguma coisa</i> (Platão, Gorg. 450c: <span class=\"greek\">τ</span>. <span class=\"greek\">τεχνῶν</span>; Ps.-Platão, Eryx. 404b; Sir 6:19; 38:34): <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀκαθαρσίας</span> <span class=\"greek\">πάσης</span>, <i>para a prática de toda espécie de impureza</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:19</a>. <span class=\"greek\">πολλαπλασιάζειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>., <i>realizar muitas espécies de trabalho</i>, GHb 297, 21 (ver também ④).</p>\n<p class=\"entry-text\"><b>② Maneira de atuar: funcionamento, operação, atividade.</b> (Platão, Prot. 353d: <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡδονῆς</span>.) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>, <i>dos anjos</i>, Hm 6, 2, 6, conjectura de Gebhardt–Harnack–Zahn com base nos manuscritos latinos e etíopes (Whittaker: <span class=\"greek\">ἐνέργεια</span>).</p>\n<p class=\"entry-text\"><b>③ Atividade comercial: negócio, comércio, empreendimento.</b> (Xen., Oec. 6, 8; Diod. S. 1, 80, 1; PLond III, 906, 6, p. 108 [128 d.C.]; PFay 93, 7; Sir 7:15.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:25</a> (Arriano, Peripl. 21, 1: <span class=\"greek\">ξόανον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παλαιᾶς</span> <span class=\"greek\">ἐργασίας</span>).</p>\n<p class=\"entry-text\"><b>④ Resultado ou produto da atividade: lucro, ganho, rendimento.</b> (Xen., Mem. 3, 10, 1; Políbio 4, 50, 3; Artemidoro 4, 57: <span class=\"greek\">ἔχειν</span> … <span class=\"greek\">ἐργασίαν</span> = «obter lucros ou salários»; PGM 4, 2438; Sb 13:19; Jos., Bell. 2, 109.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:19</a>; <span class=\"greek\">παρέχειν</span> <span class=\"greek\">ἐργασίαν</span> <span class=\"greek\">τινί</span>, <i>dar lucro a alguém</i>, versículo 16; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:24</a> (cf. a lítotes em Esopo, Fab. 112 H. = 56 P., sobre uma <span class=\"greek\">μάγος</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">βίον</span> <span class=\"greek\">πορίζουσα</span>, «uma maga que obtinha rendimentos nada pequenos»). <span class=\"greek\">πολλαπλ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>., <i>multiplicar os ganhos</i>, GHb 297, 21 (ver ①).</p>\n<p class=\"entry-text\"><b>⑤ Na expressão <span class=\"greek\">δὸς</span> <span class=\"greek\">ἐργασίαν</span></b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:58</a>, ver <span class=\"greek\">δίδωμι</span> 17a (<span class=\"greek\">ἐ</span>. = «esforços, dificuldades»; Jos., Ant. 3, 35: <span class=\"greek\">μὴ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">πόνῳ</span> <span class=\"greek\">μηδ</span>’ <span class=\"greek\">ἐργασίᾳ</span>). — DELG, s.v. <span class=\"greek\">ἔργον</span>; M-M.</p></section></article>\n<article id=\"entry-ergasterion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐργαστήριον, ίου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ergastḗrion⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte e <span class=\"greek\">ἔργον</span>; Heródoto, Aristófanes e outros; inscrições; PLond III, 897, 18, p. 207 [84 d.C.]; POxy 1455, 9; PYadin 5a I, 10; <i>Cat. Cod. Astr.</i> IX/2, p. 134, 19 e outros; Fílon.) <b>Oficina, local de trabalho</b>, MPol 13:1.</p></section></article>\n<article id=\"entry-ergastra-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔργαστρα, ων, τά</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦érgastra⟧</span><span class=\"separator\">·</span><span>substantivo neutro plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; plural com vários sentidos desde o século IV a.C.; também Sb 6771, 89, «salários».) <b>Oficinas.</b> <span class=\"greek\">ἃ</span> <span class=\"greek\">πέπονθεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φιλίπποις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐ</span>., <i>o que ele (Paulo) sofreu nas oficinas de Filipos</i> (segundo a tradução de C. Schmidt, «na casa de trabalho»), AcPl Ha 6, 5.</p></section></article>\n<article id=\"entry-ergates-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐργάτης, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ergátēs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os três verbetes anteriores; poetas trágicos, Heródoto e posteriores; empréstimo no hebraico rabínico).</p>\n<p class=\"entry-text\"><b>① Pessoa envolvida em trabalho: trabalhador, operário, obreiro.</b></p>\n<p class=\"entry-text\"><b>ⓐ Acerca de pessoas empenhadas no trabalho físico:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5:18</a>; D 13:2; <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">ἐ</span>., <i>o bom trabalhador</i>, 1 Cl 34:1. Especialmente trabalhadores agrícolas (Sófocles, Oed. R. 859 e outros; Sb 17:16; Fílon, Agr. 5 e outros: <span class=\"greek\">γῆς</span> <span class=\"greek\">ἐ</span>.): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:37</a>s.; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:4</a>; GJs 18:2 (não «papiros»). Sobre trabalhadores numa vinha: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:1</a>s., 8; <span class=\"greek\">ὁ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐ</span>., <i>trabalhador ocupado com alguma coisa</i> (Ps.-Demóstenes 35, 32: <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γεωργίαν</span> <span class=\"greek\">ἐργάται</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:25</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Figuradamente, acerca de apóstolos e mestres:</b> <span class=\"greek\">ἐργάται</span> <span class=\"greek\">δόλιοι</span>, <i>obreiros fraudulentos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11:13</a>; <span class=\"greek\">κακοὶ</span> <span class=\"greek\">ἐ</span>., <i>maus obreiros</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:2</a>; <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀνεπαίσχυντος</span>, <i>obreiro que não tem de que se envergonhar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2:15</a>. — T. Haraguchi, ZNW 84 (1993), pp. 178–195.</p>\n<p class=\"entry-text\"><b>② Pessoa que produz algo mediante sua atuação: realizador, praticante.</b> Com genitivo (Xen., Mem. 2, 1, 27: <span class=\"greek\">τ</span>. <span class=\"greek\">καλῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σεμνῶν</span>; Aristóxeno, fragmento 43: <span class=\"greek\">ἐ</span>. <span class=\"greek\">φιλίας</span>; Dio Chrys. 53 [70], 1: <span class=\"greek\">τ</span>. <span class=\"greek\">ἀργῶν</span>; Sexto 384: <span class=\"greek\">ἀληθείας</span>; GrBar 13:4: <span class=\"greek\">τῶν</span> <span class=\"greek\">τοιούτων</span>; EpArist 231: <span class=\"greek\">ἀγαθῶν</span>; Fílon, Leg. All. 1, 54: <span class=\"greek\">τ</span>. <span class=\"greek\">ἀρετῶν</span>): <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀδικίας</span>, <i>aquele que pratica injustiça, malfeitor</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:27</a> (P. Hoffmann, ZNW 58 [1967], pp. 188–214); <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀνομίας</span>, <i>praticante da iniquidade</i> (1 Mac 3:6; <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀ</span>., Just., A I, 16, 11), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:27</a>, variante de leitura; 2 Cl 4:5. — DELG, s.v. <span class=\"greek\">ἔργον</span>; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-ergon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔργον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦érgon⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Homero.) Em geral, <b>obra, ação, trabalho</b>.</p>\n<p class=\"entry-text\"><b>① Aquilo que se manifesta numa atividade de qualquer natureza: ato, ação, feito, obra.</b></p>\n<p class=\"entry-text\"><b>ⓐ Em oposição ao descanso</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:3</a>, 4 (Gn 2:2), 10. Em contraste com a palavra ou o discurso: expressão frequente para descrever pessoas de mérito excepcional, sobretudo benfeitores (Xen., Hier. 7, 2; Cyr. 6, 4, 5; Cebes 2, 2: <span class=\"greek\">λόγῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">Πυθαγόρειος</span>, «pitagórico de palavra e ação»; Luciano, Tox. 35; frequentemente em Epicteto; GDI 5039, 20 [Creta]: <span class=\"greek\">οὔτε</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἔργῳ</span>; Sir 3:8; 16:12; 4 Mac 5:38; En 14:22: <span class=\"greek\">πᾶς</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἔργον</span>; TestAbr A 9, p. 86, 26 [Stone, p. 20]: <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λόγῳ</span>; Fílon; Jos., Ant. 17, 220; C. Ap. 2, 12; Larfeld I, pp. 497s.): <span class=\"greek\">δυνατὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λόγῳ</span>, <i>poderoso em obra e palavra</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:19</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:22</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔ</span>., <i>em palavra ou em ação</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:17</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:18</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 10:11</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:16</a>a; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3:18</a>; 2 Cl 17:7; também 4:3.</p>\n<p class=\"entry-text\">Contraste semelhante entre <span class=\"greek\">ποιητὴς</span> <span class=\"greek\">ἔργου</span>, <i>aquele que pratica o que faz</i>, e o ouvinte esquecido, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:25</a>; e entre <span class=\"greek\">ἔργα</span>, <i>obras</i>, e uma <span class=\"greek\">πίστις</span>, <i>fé</i>, que nada é além de declaração verbal, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:14–26</a>. Ver J. Ropes, <i>Expositor</i>, sétima série, 5 (1908), pp. 547–556, e seu comentário (1916), ad loc.; H. Preisker, ThBl 4 (1925), pp. 16s.; E. Tobac, RHE 22 (1926), pp. 797–805; A. Meyer, <i>D. Rätsel des Jk</i> (1930), pp. 86ss.; A. Schlatter, <i>D. Brief des Jak.</i> (1932), pp. 184–207.</p>\n<p class=\"entry-text\"><b>ⓑ Manifestação, comprovação prática.</b> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, <i>a obra resultante da fé</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 1:3</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 1:11</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">διακονίας</span>, <i>obra de ministério</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:12</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προσευχῆς</span>, <i>o efeito próprio da oração</i>, AcPl Ha 4, 27. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, <i>o agir conforme a Lei</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:15</a> (talvez também a realização efetiva da Lei, como Polieno 1, 19: <span class=\"greek\">τοῦ</span> <span class=\"greek\">λογίου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>, «realização ou cumprimento de uma resposta oracular»). <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπομονὴ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τέλειον</span> <span class=\"greek\">ἐχέτω</span>, <i>que a perseverança se manifeste perfeitamente na prática</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:4</a>.</p>\n<p class=\"entry-text\"><b>ⓒ Ato, realização, feito.</b></p>\n<p class=\"entry-text\"><b><span class=\"greek\">α</span>. Obras de Deus e de Jesus, sobretudo milagres.</b> (Epicteto 3, 5, 10: <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σά</span> [= <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>]; Élio Aristides 50, 17 K. = 26, p. 506 D.: <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">θαυμαστόν</span>; Quinto de Esmirna 9, 481: <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἀθανάτων</span>, sobre a cura de Filoctetes; Js 24:29; Sl 45:9; 65:5; 85:8; JosAs 9:5; Jos., Bell. 5, 378: <span class=\"greek\">τ</span>. <span class=\"greek\">ἔργα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; C. Ap. 2, 192.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:20</a>, 36; 7:3, 21 (Diod. S. 5, 33, 5: <span class=\"greek\">ἓν</span> <span class=\"greek\">ἔργον</span>, «uma única prática»); 9:3; 10:25, 37s.; 14:10, 11, 12; 15:24; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:41</a> (Hc 1:5); 15:18, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:9</a> (Sl 94:9); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:3</a>. Sobre <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:19</a>, ver <span class=\"greek\">δικαιόω</span> ②ⓑ<span class=\"greek\">α</span>.</p>\n<p class=\"entry-text\"><b><span class=\"greek\">β</span>. Obras humanas, que revelam um caráter moral consistente.</b> Frequentemente como coletivo <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> (Sl 105:35; Jó 11:11; Jn 3:10): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:20</a>s.; 7:7; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:13</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3:12</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:2</a>, 19; 3:1, 8, 15. <span class=\"greek\">σωτῆρος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>., <i>as obras de nosso Salvador</i>, Qua.; <span class=\"greek\">τὰ</span> <span class=\"greek\">πρῶτα</span> <span class=\"greek\">ἔ</span>., <i>as primeiras obras</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:5</a>; <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span>, <i>todas as obras</i> (Am 8:7; Mq 6:16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:5</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span>, <i>segundo as obras</i> (Sl 27:4; 61:13; Pv 24:12; En 100:7; PsSol 2:16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:3</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1:9</a>; 4:14; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:23</a>; 20:12s.; também <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:17</a>. O coletivo singular <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> pode representar o plural (Sir 11:20), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:12</a>.</p>\n<p class=\"entry-text\">O contexto pode qualificar as obras como boas ou más: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:48</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:25</a>; 3 Jo 10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:13</a>; 16:11; 18:6. Como quase todas essas passagens, salvo <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:13</a>, tratam de ações más, cabe observar que <span class=\"greek\">ἔργον</span> sozinho pode designar um ato mau ou vergonhoso, como Apiano, Bell. Civ. 2, 22 §83: <span class=\"greek\">ἔργον</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἀπῆν</span>, <i>não se abstiveram de nenhum ato vergonhoso</i>; Apolônio de Rodes 4, 476; 742; Arriano, Anab. 3, 21, 4.</p>\n<p class=\"entry-text\">Com qualificativo: <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἀγαθόν</span>, <i>boa obra</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:7</a>; 13:3; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 9:8</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2:21</a>; 3:17; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:16</a>b; 3:1; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:21</a>, variante. No plural: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:10</a> (passagem mal compreendida por J. Sanders, <i>Ethics in the NT</i> [1975], p. 78; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:6</a>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 2:10</a>. <span class=\"greek\">πλήρης</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">ἀγαθῶν</span>, <i>rica em boas obras</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:36</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἔ</span>. <span class=\"greek\">καλόν</span>, <i>boa ação</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:33</a>. Plural (GrBar 15:2; Dio Chrys. 3, 52): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:32</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5:10</a>a, 25; 6:18; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:7</a>, 14; 3:8, 14; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:24</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:12</a> (W. van Unnik, NTS 1 [1954/55], pp. 92–110; cf. Diod. S. 16, 1, 1); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 1:10</a>, variante; 2 Cl 12:4. <span class=\"greek\">ἔργα</span> <span class=\"greek\">ὅσια</span>, <span class=\"greek\">δίκαια</span>, <i>ações santas, justas</i>, 2 Cl 6:9. <span class=\"greek\">ἔ</span>. <span class=\"greek\">δικαιοσύνης</span>, <i>obras de justiça</i>, B 1:6 (PsSol 18:8). <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span>, <i>por obras praticadas em justiça</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:5</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <i>as obras que Deus deseja</i> (Jr 31:10; 1 Esdr 7:9, 15), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:28</a>; cf. versículo 29. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">μου</span>, <i>minhas obras</i>, isto é, de Cristo (<span class=\"greek\">Χριστοῦ</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:26</a>; <span class=\"greek\">ἔργα</span> <span class=\"greek\">πεπληρωμένα</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, <i>obras completas diante de Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:2</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄξια</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μετανοίας</span>, <i>obras dignas do arrependimento</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:20</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, <i>obras que acompanham a fé</i>, Hs 8, 9, 1; <span class=\"greek\">ἔ</span>. <span class=\"greek\">αἰώνιον</span>, <i>obra imperecível</i>, IPol 8:1; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀβραάμ</span>, <i>obras semelhantes às de Abraão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:39</a>; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πέμψαντός</span> <span class=\"greek\">με</span>, <i>as obras daquele que me enviou</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:4</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἔργα</span> <span class=\"greek\">πονηρά</span>, <i>obras más</i> (1 Esdr 8:83; En 98:6; Taciano 23:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:21</a>; 2 Jo 11; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:19</a>; 7:7; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3:12</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πονηροῦ</span>, <i>de toda obra má</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:18</a>. Também <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρᾶς</span> <span class=\"greek\">ὁδοῦ</span>, <i>obras do mau caminho</i>, B 4:10; <span class=\"greek\">νεκρά</span>, <i>obras mortas</i>, isto é, que conduzem à morte, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>; 9:14; <span class=\"greek\">ἄκαρπα</span>, <i>ações infrutíferas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:11</a>; <span class=\"greek\">ἄνομα</span>, <i>obras ilícitas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2:8</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνομίας</span>, <i>obras da iniquidade</i>, B 4:1; Hs 8, 10, 3; <span class=\"greek\">ἔργα</span> <span class=\"greek\">ἀσεβείας</span>, <i>atos de impiedade</i>, Jd 15 (Just., A I, 23, 3: <span class=\"greek\">ἀσεβῆ</span> <span class=\"greek\">ἔ</span>.).</p>\n<p class=\"entry-text\"><span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span>, <i>obras das trevas</i>, isto é, da incredulidade, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:12</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:11</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, <i>obras provenientes da carne</i>, isto é, do pecado, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:19</a>; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ὑμῶν</span>, <i>obras como as praticadas por vosso pai</i> (o diabo), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:41</a>; <span class=\"greek\">τῶν</span> <span class=\"greek\">Νικολαϊτῶν</span>, <i>dos nicolaítas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:6</a>; <span class=\"greek\">κρύφια</span>, <span class=\"greek\">φανερὰ</span> <span class=\"greek\">ἔ</span>., <i>ações secretas, manifestas</i>, 2 Cl 16:3.</p>\n<p class=\"entry-text\">Frequentemente em Paulo, <span class=\"greek\">ἔργα</span> <span class=\"greek\">νόμου</span>, <i>obras que a Lei ordena realizar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:20</a>, 28; cf. versículo 27; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:16</a>; 3:2, 5, 10 (cf. 4QMMT 3, 27 [= <i>A Facsimile Edition of the Dead Sea Scrolls</i>, ed. R. Eisenman/J. Robinson, I, 1991, p. xxxi, fig. 8, coluna c, linha 29]; M. Abegg, «Paul, ‘Works of the Law’ and MMT», BAR 20/6 [1994], pp. 52–55; J. Dunn, NTS 43 [1997], pp. 147–153). Também simplesmente <span class=\"greek\">ἔργα</span>, com o mesmo sentido, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:2</a>, 6; 9:12, 32; 11:6; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:9</a>; ver E. Lohmeyer, ZNW 28 (1929), pp. 177–207. Ver ainda <span class=\"greek\">δικαιοσύνη</span> ③, final.</p>\n<p class=\"entry-text\"><b>② Aquilo que se faz como atividade regular: trabalho, ocupação, tarefa.</b> (Aristófanes, Av. 862; Xen., Mem. 2, 10, 6; Arriano, Anab. 5, 23, 1; Epicteto 1, 16, 21; Sir 11:20; TestSol 1:2 e outros; Just., A II, 3, 5: <span class=\"greek\">βασιλικόν</span>.) Com genitivo daquele que designa a tarefa: <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, <i>do Senhor</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.58\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:58</a>; 16:10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:30</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">διδόναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">αὐτοῦ</span>, <i>atribuir sua tarefa a alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:34</a>; <span class=\"greek\">πληροῦν</span> <span class=\"greek\">ἔ</span>., <i>cumprir uma tarefa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:26</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τελειοῦν</span>, <i>concluir a obra</i> (Dionísio de Halicarnasso 3, 69, 2: <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκοδομῆς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">εἰργάσατο</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴν</span> <span class=\"greek\">ἐτελείωσε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>; 2 Esdr 16:3, 16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17:4</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:34</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔργου</span>, <i>a encarregada da oficina</i>, GJs 2:2 (ver de Strycker, ad loc.). Acerca do trabalho e encargo dos apóstolos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:2</a>; 15:38. <span class=\"greek\">οἱ</span> <span class=\"greek\">πιστευθέντες</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοιοῦτο</span>, <i>aqueles a quem Deus confiou tarefa tão importante</i>, 1 Cl 43:1; <span class=\"greek\">καρπὸς</span> <span class=\"greek\">ἔργου</span>, <i>fruto do trabalho</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:22</a>.</p>\n<p class=\"entry-text\">Amar alguém <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">αὐτοῦ</span>, <i>em razão do que essa pessoa fez</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5:13</a>. Sobre uma função ou cargo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3:1</a> (também é possível a acepção ④). <span class=\"greek\">ἔ</span>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">εὐαγγελιστοῦ</span>, <i>exercer o trabalho de evangelista</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:5</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">συγγενικὸν</span> <span class=\"greek\">ἀπαρτίζειν</span>, <i>cumprir uma tarefa apropriada, natural</i>, IEph 1:1.</p>\n<p class=\"entry-text\"><b>③ Aquilo que se produz mediante trabalho: produto, realização, obra.</b> (Homero e outros; Gn 2:2; 3 Km 7:15, 19; Jr 10:3; 1 Esdr 5:44; TestAbr A 13, p. 93, 11 [Stone, p. 34]: <span class=\"greek\">εἴ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">κατακαύσει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πὺρ</span>; Just., D. 88, 8; Melitão, P. 36, 244.) «Obra» em sentido passivo. Especialmente edifícios (Aristófanes, Av. 1125; Políbio 5, 3, 6; Diod. S. 1, 31, 9; Apiano, Mithrid. 30 §119; Arriano, Anab. 6, 18, 2; Dionísio de Bizâncio §27; IG IV²/1, 106, 56; 114, 31 e outros; PPetr III, 43 [2] I, 2 [séc. III a.C.]: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span>, «para as construções»; 1 Mac 10:11; SibOr 4, 59; E. Peterson, Biblica 22 [1941], pp. 439–441), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 3:13</a>, 14, 15. Talvez se trate também de construção em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9:1</a> e <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:20</a> (ver <span class=\"greek\">καταλύω</span> ②ⓑ).</p>\n<p class=\"entry-text\"><span class=\"greek\">γῆ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">ἔ</span>., <i>a terra e as obras que nela existem</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3:10</a> (F. Danker, ZNW 53 [1962], pp. 82–86, propõe ler <span class=\"greek\">καὶ</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">ἔργα</span>). Imagens de divindades como <span class=\"greek\">ἔργα</span> <span class=\"greek\">ἀνθρώπων</span>, <i>obras humanas</i>, 2 Cl 1:6 (Herodas 4, 26: <span class=\"greek\">ἔργα</span> <span class=\"greek\">καλά</span>, acerca de esculturas; Atenágoras 17:3s.).</p>\n<p class=\"entry-text\">Igualmente na expressão <span class=\"greek\">ἔργον</span> <span class=\"greek\">χειρός</span>, <i>obra da mão</i> (cf. En 98:5; ApcEsdr 1:10; Herodas 7, 2s.: <span class=\"greek\">τῶν</span> <span class=\"greek\">σῶν</span> … <span class=\"greek\">χειρέων</span> <span class=\"greek\">νοῆρες</span> <span class=\"greek\">ἔργον</span>; Epicteto 3, 7, 24: <span class=\"greek\">τὰ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">ἔργα</span>; Jos., Bell. 3, 268, sobre atos corajosos, <span class=\"greek\">χειρῶν</span> <span class=\"greek\">ἔργα</span>; cf. Just., D. 23, 5, acerca da circuncisão como não sendo <span class=\"greek\">ἔργον</span> <span class=\"greek\">δικαιοσύνης</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">τινος</span>, <i>a obra das mãos de alguém, aquilo que alguém fez</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:41</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:20</a> (cf. Is 17:8; Just., A I, 20, 5 e outros).</p>\n<p class=\"entry-text\">Sobre o mundo criado por Deus (Celso 4, 99), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:10</a> (Sl 101:26; Ar. 4:24 e outros); 2:7, variante; B 5:10; 15:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, <i>as obras do diabo</i> (Arriano, Anab. 1, 11, 7: <span class=\"greek\">Τρωικὸν</span> <span class=\"greek\">ἔ</span>., «empreendimento troiano», isto é, a guerra de Troia), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3:8</a>; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θηλείας</span>, <i>obras da mulher</i>, com referência ao desejo sensual, como Horápolo 1, 11, p. 18: <span class=\"greek\">θηλείας</span> <span class=\"greek\">ἔργον</span>, e Longo 4, 19, 5: <span class=\"greek\">ἔργα</span> <span class=\"greek\">γυναικῶν</span>, GEg 252, 56; sobre adultério, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:22</a>.</p>\n<p class=\"entry-text\"><b>④ Algo relacionado ao assunto tratado: coisa, questão, assunto.</b> (Homero e outros.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:38</a>; <span class=\"greek\">κρεῖττον</span>, <i>coisa melhor</i>, IRo 2:1 (cf. GrBar 5:3: <span class=\"greek\">μείζονα</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἔργα</span>); <span class=\"greek\">ἔ</span>. <span class=\"greek\">εὐφροσύνης</span>, <i>coisa alegre</i>, B 10:11; <span class=\"greek\">οὐ</span> <span class=\"greek\">πεισμονῆς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>., <i>não se trata de persuasão</i>, IRo 3:3; <span class=\"greek\">οὐ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἐπαγγελίας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>., <i>não é questão do que agora professamos</i>, IEph 14:2. Talvez também <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3:1</a> (ver ② acima). — J. Kleist, «‘Ergon’ in the Gospels», CBQ 6 (1944), pp. 61–68; DELG; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-ergoparektes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐργοπαρέκτης, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ergoparéktēs⟧</span><span class=\"separator\">·</span><span>substantivo masculino; hápax</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἔργον</span> e <span class=\"greek\">παρέχω</span>; <i>hápax legómenon</i>.) Literalmente, <b>aquele que fornece trabalho: empregador</b>, 1 Cl 34:1.</p></section></article>\n<article id=\"entry-erethizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρεθίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦erethízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἠρέθισα</span>; particípio aoristo passivo <span class=\"greek\">ἐρεθισθείς</span>, 2 Mac 14:27; futuro passivo, terceira pessoa do singular <span class=\"greek\">ἐρεθισθήσεται</span>, Dn 11:10, 25 (ver <span class=\"greek\">ἔρις</span>; Homero e outros; Epicteto, Ench. 20; LXX; TestSol 4:6; 8:5 PC; TestDan 4:4). <b>Provocar em alguém uma reação como resposta a um desafio: excitar, incitar, estimular.</b> Em geral, em sentido desfavorável: <b>irritar, exasperar, amargurar</b>, como <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span>, <i>os filhos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:21</a> (cf. Epicteto, loc. cit., onde <span class=\"greek\">ἐ</span>. retoma os precedentes <span class=\"greek\">λοιδορεῖν</span> e <span class=\"greek\">τύπτειν</span>; 1 Mac 15:40; Fílon, Ebr. 16; Jos., Bell. 2, 414; Ant. 4, 169; 20, 175; Atenágoras, R. 75, 22).</p>\n<p class=\"entry-text\">Em <b>sentido favorável</b>, acerca do exemplo que encoraja (Élio Aristides 28, 75 K. = 49, p. 516 D.; Apiano, Iber. 26 §103), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 9:2</a>. — DELG, s.v. <span class=\"greek\">ἐρέθω</span>; M-M; EDNT; Spicq.</p></section></article>\n<article id=\"entry-ereido-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρείδω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ereídō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐρείσω</span>, Pv 3:26; TestSol 6:10; primeiro aoristo <span class=\"greek\">ἤρεισα</span> (Homero e outros; LXX; Jos., Bell. 7, 283; Ant. 8, 133; SibOr 4, 106). <b>Fincar em alguma coisa, cravar, encravar, ficar firmemente preso.</b> (Ésquilo, Ag. 976; Plutarco, Numa 60 [2, 2]; Crass. 554 [19, 4].) Sobre a proa de um navio, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:41</a> (cf. Píndaro, P. 10, 51s.: <span class=\"greek\">ταχὺ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἄγκυραν</span> <span class=\"greek\">ἔρεισον</span> <span class=\"greek\">χθονὶ</span> <span class=\"greek\">πρώραθε</span>, <i>lança depressa a âncora da proa e deixa-a prender-se ao fundo</i>). — DELG; M-M.</p></section></article>\n<article id=\"entry-ereugomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρεύγομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ereúgomai⟧</span><span class=\"separator\">·</span><span>verbo; depoente médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐρεύξομαι</span> (Homero e outros; LXX; SibOr 4, 81). Originalmente «arrotar»; posteriormente <b>expressar vigorosamente algo inteligível: proferir, declarar, proclamar.</b> (Cf. a imagem em Calímaco, POxy 1011, folha 1, verso, 7 = fragmento 75, 7 Pf. I 77, mas ali <span class=\"greek\">ἐξερυγάννω</span> ocorre em tmese e, satiricamente, significa «arrotar a própria história».)</p>\n<p class=\"entry-text\">Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i>: <span class=\"greek\">κεκρυμμένα</span>, <i>coisas ocultas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:35</a> (cf. Sl 77:2: <span class=\"greek\">φθέγξομαι</span>; quanto à imagem de expressão vigorosa, cf. Jó 32:19s.); <span class=\"greek\">ῥῆμα</span>, <i>uma palavra</i>, 1 Cl 27:7 (Sl 18:3). — DELG 1; M-M.</p></section></article>\n<article id=\"entry-ereunao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρευνάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ereunáō⟧</span><span class=\"separator\">·</span><span>verbo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐρευνάω</span>; ver <span class=\"greek\">ἐραυνάω</span>.</p></section></article>\n<article id=\"entry-ereunetes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρευνητής</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ereunētḗs⟧</span><span class=\"separator\">·</span><span>substantivo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐρευνητής</span>; ver <span class=\"greek\">ἐραυνητής</span>.</p></section></article>\n<article id=\"entry-eremia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρημία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦erēmía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Região desabitada ou solitária, normalmente com vegetação escassa: deserto, região deserta.</b> (Ver o verbete seguinte; assim Ésquilo, Heródoto e outros; BGU 888, 15 [séc. II d.C.]; PGrenf II, 84, 4; LXX; Fílon; Jos., Bell. 3, 515 [perto do Jordão]; Just., A I, 12, 6; Melitão, P. 94, 722; empréstimo no hebraico rabínico.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:33</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:4</a>; junto de <span class=\"greek\">ὄρη</span>, <i>montanhas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:38</a>. Em contraste com <span class=\"greek\">πόλις</span>, <i>cidade</i> (como Ez 35:4; Jos., Ant. 2, 24; Vi. 11), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11:26</a>. GJs 16:2b (região montanhosa). — DELG, s.v. <span class=\"greek\">ἐρῆμος</span>; M-M; TW.</p></section></article>"};
